// Label Occlusion — Text, route: jsx
// Source: occlusion
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import * as d3 from 'd3';
import { useMemo } from 'react';

// ---- inlined from occlusion ----
type LabeledPoint = { id: number; x: number; y: number; label: string; weight: number };

const PREFIX = ['Ald', 'Bre', 'Cor', 'Dor', 'Eln', 'Fal', 'Gar', 'Hol', 'Ish', 'Jor', 'Kel', 'Lum', 'Mor', 'Ner', 'Orv', 'Pyl'];
// 16 x 15 = 240 combinations for 240 draws, so every label below is unique.
const SUFFIX = ['ath', 'bury', 'cove', 'dell', 'ford', 'gate', 'holm', 'iren', 'kirk', 'mere', 'nook', 'reach', 'stad', 'thorn', 'vale'];

const nameFor = (i: number) =>
  PREFIX[i % PREFIX.length] + SUFFIX[Math.floor(i / PREFIX.length) % SUFFIX.length];

// Seeded LCG, not Math.random, so the same cloud survives every hot reload.
const source = d3.randomLcg(0.4217);
const uniform = d3.randomUniform.source(source)(0, 1);
const normal = d3.randomNormal.source(source)(0, 1);

// Three dense knots plus a uniform scatter, so label density varies enough that some
// regions lose almost every label while sparse corners keep all of theirs.
const CLUSTERS = [
  { x: 0.26, y: 0.4, spread: 0.09 },
  { x: 0.58, y: 0.28, spread: 0.13 },
  { x: 0.72, y: 0.7, spread: 0.08 }
];

const occlusionPoints: LabeledPoint[] = d3
  .range(240)
  .map((i) => {
    const knot = CLUSTERS[i % CLUSTERS.length];
    const clustered = uniform() < 0.62;
    return {
      id: i,
      x: clustered ? knot.x + normal() * knot.spread : uniform(),
      y: clustered ? knot.y + normal() * knot.spread : uniform(),
      label: nameFor(i),
      weight: uniform()
    };
  })
  .filter((p) => p.x > 0.01 && p.x < 0.99 && p.y > 0.01 && p.y < 0.99);

/** Points in unit space, each with a label and a priority weight; higher weight wins a collision. */
export type Data = { id: number; x: number; y: number; label: string; weight: number }[];

const MARGIN = { top: 14, right: 14, bottom: 30, left: 14 };
const DOT_R = 2;
const PAD = 1.5;
// Mean advance width of the gallery sans-serif as a fraction of font size. The notebook
// measures real boxes with getBoundingClientRect; there is no DOM here at layout time.
const CHAR_WIDTH = 0.55;

type Box = { x: number; y: number; w: number; h: number };
type Candidate = Data[number] & {
  cx: number;
  cy: number;
  fontSize: number;
  box: Box;
  visible: boolean;
};

function intersects(a: Box, b: Box): boolean {
  return !(a.x + a.w < b.x || b.x + b.w < a.x || a.y + a.h < b.y || b.y + b.h < a.y);
}

export default function Occlusion({
  data = occlusionPoints,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(() => d3.scaleLinear().domain([0, 1]).range([0, innerWidth]), [innerWidth]);
  const y = useMemo(() => d3.scaleLinear().domain([0, 1]).range([innerHeight, 0]), [innerHeight]);

  // One priority-ordered sweep: heaviest label first, each kept only if its estimated box
  // clears the frame and misses every box already placed.
  const candidates: Candidate[] = useMemo(() => {
    const placed: Box[] = [];
    return data
      .slice()
      .sort((a, b) => b.weight - a.weight)
      .map((p) => {
        const fontSize = 9 + p.weight * 6;
        const cx = x(p.x);
        const cy = y(p.y);
        const w = p.label.length * fontSize * CHAR_WIDTH + PAD * 2;
        const h = fontSize * 1.1 + PAD * 2;
        const box = { x: cx - w / 2, y: cy - DOT_R - 2 - h, w, h };
        const fits = box.x >= 0 && box.x + box.w <= innerWidth && box.y >= 0;
        const visible = fits && !placed.some((other) => intersects(box, other));
        if (visible) placed.push(box);
        return { ...p, cx, cy, fontSize, box, visible };
      });
  }, [data, x, y, innerWidth]);

  const kept = candidates.filter((c) => c.visible).length;

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Label occlusion demo: ${data.length} points carrying invented place names, swept in priority order so that only the ${kept} labels whose boxes do not collide are drawn. The rest stay as bare points with their text ghosted.`}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {candidates.map((c) => (
          <circle
            key={c.id}
            cx={c.cx}
            cy={c.cy}
            r={DOT_R}
            fill={c.visible ? 'var(--accent)' : 'var(--muted)'}
            fillOpacity={c.visible ? 1 : 0.45}
          />
        ))}
        {/* Suppressed labels stay on screen at a tenth opacity so the decluttering is legible
            as an effect rather than as an absence. */}
        {candidates
          .filter((c) => !c.visible)
          .map((c) => (
            <text
              key={`ghost-${c.id}`}
              x={c.cx}
              y={c.box.y + c.box.h - PAD}
              textAnchor="middle"
              fontSize={c.fontSize}
              fill="var(--text)"
              opacity={0.1}
            >
              {c.label}
            </text>
          ))}
        {candidates
          .filter((c) => c.visible)
          .map((c) => (
            <text
              key={`label-${c.id}`}
              x={c.cx}
              y={c.box.y + c.box.h - PAD}
              textAnchor="middle"
              fontSize={c.fontSize}
              fill="var(--text)"
            >
              {c.label}
            </text>
          ))}
        <text x={0} y={innerHeight + 22} fontSize={11} fill="var(--muted)">
          {kept} of {data.length} labels drawn. Larger type is higher priority.
        </text>
      </g>
    </svg>
  );
}
